// Função para gerar dados simulados de sensor (temperatura e umidade)
// Formato de saída: { timestamp: "", temperatura: 0, umidade: 0 }

// Configurações iniciais
var temperaturaBase = 25;  // Valor base de temperatura em °C
var umidadeBase = 60;      // Valor base de umidade em %
var variacaoTemp = 5;      // Variação máxima de temperatura
var variacaoUmi = 20;      // Variação máxima de umidade

// Gera um valor aleatório dentro de um intervalo
function getRandom(min, max) {
    return Math.random() * (max - min) + min;
}

// Gera uma variação suave baseada no timestamp
function getVariation(base, variation, periodMinutes) {
    const now = new Date();
    const cycle = Math.sin(now.getMinutes() / periodMinutes * Math.PI * 2);
    return base + (cycle * variation / 2);
}

// Gera os dados do sensor
var timestamp = new Date().toISOString();
var temperatura = getVariation(temperaturaBase, variacaoTemp, 60).toFixed(2);
var umidade = getVariation(umidadeBase, variacaoUmi, 90).toFixed(2);

// Adiciona um pouco de ruído aleatório para tornar mais realista
temperatura = (parseFloat(temperatura) + getRandom(-0.5, 0.5)).toFixed(2);
umidade = (parseFloat(umidade) + getRandom(-2, 2)).toFixed(2);

// Garante que os valores estão dentro de limites razoáveis
temperatura = Math.max(15, Math.min(40, parseFloat(temperatura))).toFixed(2);
umidade = Math.max(30, Math.min(90, parseFloat(umidade))).toFixed(2);

// Cria a mensagem de saída
msg.payload = {
    timestamp: timestamp,
    temperatura: parseFloat(temperatura),
    umidade: parseFloat(umidade)
};

return msg;
